import{expectFunction,expectObjectRecord}from"../internal/authored-module.js";import{assertHookForm}from"../public/definitions/hook.js";import{removedEventKeyMessage}from"../public/definitions/removed-event-keys.js";import{ResolveAgentError,loadResolvedModuleExport}from"./resolve-helpers.js";import{toErrorMessage}from"../shared/errors.js";async function resolveHookDefinition(e,t,n){try{let r=await loadResolvedModuleExport({definition:e,kindLabel:`hook`,moduleMap:t,nodeId:n}),i=expectObjectRecord(r,describe(e,`to return an object`));assertHookForm(i,`The hook export "${e.exportName??`default`}" from "${e.logicalPath}"`);let a={},o=i.events;if(o!==void 0){let t=expectObjectRecord(o,describe(e,"to expose `events` as an object"));for(let[n,r]of Object.entries(t)){if(r===void 0)continue;let t=removedEventKeyMessage(n);if(t!==void 0)throw new ResolveAgentError(`Hook "${e.logicalPath}" handles ${t}`,{logicalPath:e.logicalPath,sourceId:e.sourceId});a[n]=expectFunction(r,describe(e,`to provide a function for "events.${n}"`))}}return{events:a,exportName:e.exportName,logicalPath:e.logicalPath,slug:e.slug,sourceId:e.sourceId,sourceKind:`module`}}catch(t){throw t instanceof ResolveAgentError?t:new ResolveAgentError(`Failed to attach hook handlers from "${e.logicalPath}": ${toErrorMessage(t)}`,{logicalPath:e.logicalPath,sourceId:e.sourceId})}}function describe(e,t){return`Expected the hook export "${e.exportName??`default`}" from "${e.logicalPath}" ${t}.`}export{resolveHookDefinition};