import{toErrorMessage}from"#shared/errors.js";import{assertDynamicSentinelKeys,dynamicEvaluate,isDynamicSentinel,isFrameworkDefinition}from"#dynamic/definition.js";import{ResolveAgentError,loadResolvedModuleExport}from"#runtime/resolve-helpers.js";async function resolveDynamicDefinition(e,t){let describe=n=>`Expected the ${t.kindLabel} export "${e.exportName??`default`}" from "${e.logicalPath}" ${n}.`;try{let n=await loadResolvedModuleExport({definition:e,kindLabel:t.kindLabel,moduleMap:t.moduleMap,nodeId:t.nodeId});if(!isDynamicSentinel(n))throw Error(describe(`to be created by defineDynamic()`));return assertDynamicSentinelKeys(n,`The ${t.kindLabel} export "${e.exportName??`default`}" from "${e.logicalPath}":`),{...e,...isFrameworkDefinition(n)?{framework:!0}:{},evaluate:dynamicEvaluate(n)}}catch(n){throw n instanceof ResolveAgentError?n:new ResolveAgentError(`Failed to resolve ${t.kindLabel} from "${e.logicalPath}": ${toErrorMessage(n)}`,{logicalPath:e.logicalPath,sourceId:e.sourceId})}}export{resolveDynamicDefinition};