import{frameworkTool}from"./framework-tool.js";import{defineJsonSchema}from"#tools/schema.js";import{defineTool}from"#tools/definition.js";import{toolLabel}from"#tools/tool-label.js";import{BASH_YIELD_SECONDS,executeBashOnSandbox}from"#execution/sandbox/bash.js";const BASH_INPUT_SCHEMA=defineJsonSchema({type:`object`,properties:{command:{type:`string`,description:`The shell command to execute.`}},required:[`command`],additionalProperties:!1}),BASH_OUTPUT_SCHEMA=defineJsonSchema({oneOf:[{type:`object`,properties:{status:{const:`completed`},exitCode:{type:`number`},stderr:{type:`string`},stdout:{type:`string`},truncated:{type:`boolean`}},required:[`status`,`exitCode`,`stderr`,`stdout`,`truncated`],additionalProperties:!1},{type:`object`,properties:{status:{const:`running`},pid:{type:`number`},outputDirectory:{type:`string`},message:{type:`string`},stderr:{type:`string`},stdout:{type:`string`},truncated:{type:`boolean`}},required:[`status`,`pid`,`outputDirectory`,`message`,`stderr`,`stdout`,`truncated`],additionalProperties:!1}]}),bash=frameworkTool(defineTool({label:{start:e=>toolLabel(`Run`,e.command)},description:`Execute a shell command in the shared workspace environment. A command still running after ${BASH_YIELD_SECONDS} seconds keeps running in the background and returns status "running" with its output so far and how to check on or stop it.`,async execute(e,t){return await executeBashOnSandbox(await t.getSandbox(),e,{abortSignal:t.abortSignal})},inputSchema:BASH_INPUT_SCHEMA,outputSchema:BASH_OUTPUT_SCHEMA}));export{BASH_INPUT_SCHEMA,BASH_OUTPUT_SCHEMA,bash,bash as default};