import{publishSessionEvents}from"#execution/publish-session-events.js";import{withSessionStateDelta}from"#execution/session/step-state-delta.js";import{controlSettled}from"#harness/facts.js";async function settleControlDeliveryStep(e){"use step";return await withSessionStateDelta(e,t=>publishSessionEvents(t,controlSettled(e.settlement)))}export{settleControlDeliveryStep};